-- Function: public.fn_get_attendance_summary
-- Backup generated on 2026-10-25 20:33:01

CREATE OR REPLACE FUNCTION public.fn_get_attendance_summary(p_tenant_id uuid, p_date date)  RETURNS TABLE(expected_children integer, present_children integer, absent_children integer, late_children integer, expected_teachers integer, present_teachers integer, absent_teachers integer, late_teachers integer)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT          (SELECT COUNT(*)::INT FROM children WHERE tenant_id = p_tenant_id AND is_active = true) AS expected_children,         (SELECT COUNT(*)::INT FROM child_attendance WHERE tenant_id = p_tenant_id AND attendance_date = p_date AND status = 'Present') AS present_children,         (SELECT COUNT(*)::INT FROM child_attendance WHERE tenant_id = p_tenant_id AND attendance_date = p_date AND status = 'Absent') AS absent_children,         (SELECT COUNT(*)::INT FROM child_attendance WHERE tenant_id = p_tenant_id AND attendance_date = p_date AND status = 'Late') AS late_children,                  (SELECT COUNT(*)::INT FROM teachers WHERE tenant_id = p_tenant_id AND status != 'Inactive') AS expected_teachers,         (SELECT COUNT(*)::INT FROM teacher_attendance WHERE tenant_id = p_tenant_id AND attendance_date = p_date AND status = 'Present') AS present_teachers,         (SELECT COUNT(*)::INT FROM teacher_attendance WHERE tenant_id = p_tenant_id AND attendance_date = p_date AND status = 'Absent') AS absent_teachers,         (SELECT COUNT(*)::INT FROM teacher_attendance WHERE tenant_id = p_tenant_id AND attendance_date = p_date AND status = 'Late') AS late_teachers; END; $function$ ;
